import { ScrollView, Text, TouchableOpacity, View } from 'react-native'
import { defineStyles } from '@/utils/defineStyles'
import { ThinkingStatusIndicator } from './ThinkingStatusIndicator'
import { Image } from 'expo-image'
import { colors, Theme, useTheme } from '@/theme'
import Animated, {
	useAnimatedStyle,
	useSharedValue,
	withTiming,
	runOnUI,
	measure,
	useAnimatedRef
} from 'react-native-reanimated'
import { useEffect, useState, useMemo } from 'react'
import { StreamingText } from '../hooks/useStreaming'
import { AnimatePresence, MotiView } from 'moti'
import { LinearGradient } from 'expo-linear-gradient'
import Markdown from 'react-native-markdown-display'
import { MESSAGE_GAP } from '@/constants'
import { useChatStore } from '../store/chatStore'

const MAX_SUBTEXT_HEIGHT = 120

const DomainIcons = ({ domains }: { domains: string[] }) => {
	return (
		<View style={styles.domainIcons}>
			{domains.map((domain) => (
				<Image
					key={domain}
					style={styles.domainIcon}
					source={{
						uri: `https://t0.gstatic.com/faviconV2?client=SOCIAL&type=FAVICON&fallback_opts=TYPE,SIZE,URL&url=${domain}&size=32`
					}}
				/>
			))}
		</View>
	)
}

interface ThinkingBlockProps {
	text: string
	subtext: string
	status: string
	isLatest: boolean
	domains: string
	thinkingType: string
	shouldAnimate: boolean
	isOnlyBlock: boolean
	messageId: string
}

export const ThinkingBlock = ({
	text,
	subtext,
	status,
	isLatest,
	domains,
	thinkingType,
	shouldAnimate,
	isOnlyBlock,
	messageId
}: ThinkingBlockProps) => {
	const { theme } = useTheme()
	const isRunning = status === 'running' && isLatest
	const isSuccess = status === 'success'
	const isCancelled = status === 'cancelled'
	const currentMessageId = useChatStore((state) => state.value.currentMessageId)
	const chatState = useChatStore((state) => state.value.chatState)

	const displayText = isCancelled ? 'Cancelled' : text

	const subtextHeight = useSharedValue(0)
	const subtextRef = useAnimatedRef<ScrollView>()

	const [isCollapsed, setIsCollapsed] = useState(false)
	const [shouldShowGradient, setShouldShowGradient] = useState(false)

	const domainsArray = useMemo(
		() => domains?.split(',').filter((domain) => domain !== '') || [],
		[domains]
	)

	// markdown has built in margin top and bottom for paragraph
	const markDownStyle = {
		body: {
			...styles.subText(theme)
		},
		paragraph: {
			marginTop: 0,
			marginBottom: 0
		},
		code_inline: {
			backgroundColor: colors[theme].gray[50]
		}
	}

	const showTopBlockGradient = shouldShowGradient && shouldAnimate

	const animatedCollapsibleBlock = useAnimatedStyle(() => {
		if (subtextHeight.get() === 0) return {}
		return {
			height: withTiming(isCollapsed ? 0 : subtextHeight.get(), {
				duration: 250
			}),
			overflow: 'hidden'
		}
	}, [isCollapsed, subtextHeight])

	useEffect(() => {
		if (shouldAnimate) return
		const id = requestAnimationFrame(() => {
			runOnUI(() => {
				'worklet'
				const subtextMeasurements = measure(subtextRef)
				if (
					subtextMeasurements &&
					subtextMeasurements.height &&
					subtextMeasurements.height > 0
				) {
					subtextHeight.set(subtextMeasurements.height)
				}
			})()
		})

		return () => cancelAnimationFrame(id)
	}, [shouldAnimate, subtext, subtextHeight, subtextRef])

	return (
		<View
			style={[
				styles.thinkingBlockContainer,
				shouldAnimate && !isOnlyBlock && { paddingLeft: 28 }
			]}
		>
			<TouchableOpacity
				style={styles.headerContainer}
				onPress={() => {
					setIsCollapsed((prev) => !prev)
				}}
			>
				<View style={styles.prefixContainer}>
					<ThinkingStatusIndicator
						status={{ isRunning, isSuccess, isCancelled, isLatest }}
						data={{ domainsArray, thinkingType }}
					/>
				</View>
				<AnimatePresence exitBeforeEnter>
					<MotiView
						key={displayText}
						style={styles.transcriptContainer}
						from={
							isLatest
								? { opacity: 0, translateY: -6 }
								: { opacity: 1, translateY: 0 }
						}
						animate={{ opacity: 1, translateY: 0 }}
						exit={
							isLatest
								? { opacity: 0, translateY: 6 }
								: { opacity: 1, translateY: 0 }
						}
						transition={
							isLatest
								? { type: 'timing', duration: 300 }
								: { type: 'timing', duration: 0 }
						}
					>
						<Text
							key={displayText}
							style={[
								styles.modalText(theme),
								isCancelled && { color: colors[theme].gray[400] }
							]}
						>
							{displayText}
						</Text>
						{domainsArray && domainsArray.length > 0 && (
							<DomainIcons domains={domainsArray} />
						)}
					</MotiView>
				</AnimatePresence>
			</TouchableOpacity>
			<Animated.View
				style={[
					isOnlyBlock && styles.subTextContainer,
					!shouldAnimate && animatedCollapsibleBlock,
					shouldAnimate && {
						maxHeight: MAX_SUBTEXT_HEIGHT,
						display: isRunning || isSuccess ? 'flex' : 'none'
					}
				]}
			>
				<AnimatePresence>
					<MotiView
						from={{ opacity: 0 }}
						animate={{ opacity: showTopBlockGradient ? 1 : 0 }}
						exit={{ opacity: 0 }}
						transition={{ type: 'timing', duration: 300 }}
						style={[styles.thinkingBlockGradient, !isOnlyBlock && { left: 0 }]}
					>
						<LinearGradient
							colors={[
								`${colors[theme].gray[25]}FF`,
								`${colors[theme].gray[25]}00`
							]}
							pointerEvents="none"
							style={{ width: '100%', height: '100%' }}
						/>
					</MotiView>
				</AnimatePresence>
				<ScrollView
					ref={subtextRef}
					showsVerticalScrollIndicator={false}
					onContentSizeChange={(_, contentHeight) => {
						setShouldShowGradient(contentHeight > MAX_SUBTEXT_HEIGHT)
						subtextRef.current?.scrollToEnd({ animated: true })
					}}
				>
					{shouldAnimate &&
					chatState === 'GENERATING' &&
					currentMessageId === messageId ? (
						<StreamingText text={subtext} customStyles={markDownStyle} />
					) : (
						<Markdown style={markDownStyle}>{subtext}</Markdown>
					)}
				</ScrollView>
			</Animated.View>
		</View>
	)
}

const styles = defineStyles({
	thinkingBlockContainer: {
		gap: MESSAGE_GAP
	},
	prefixContainer: {
		position: 'absolute',
		top: 0,
		left: 0,
		height: 22,
		justifyContent: 'center'
	},
	headerContainer: {
		flexDirection: 'row',
		paddingLeft: 28
	},
	transcriptContainer: {
		flex: 1,
		gap: 6
	},
	textOverride: {
		fontWeight: '600'
	},
	modalText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[900],
		lineHeight: 22
	}),
	domainIcons: {
		flexDirection: 'row',
		alignItems: 'center'
	},
	domainIcon: {
		width: 16,
		height: 16,
		borderRadius: 50,
		marginRight: -2
	},
	subTextContainer: {
		paddingLeft: 28
	},
	subText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[400],
		lineHeight: 22
	}),
	thinkingBlockGradient: {
		position: 'absolute',
		top: 0,
		left: 28,
		right: 0,
		width: '100%',
		height: 40,
		zIndex: 2
	}
})
